export const SEED_FILES: Record<string, string> = {
  "daily-report.prompt.md": "# Daily Interrupt Duty Report\n\nYou are the editor of the Rancher UI interrupt duty daily report. You do not analyse the items\nyourself: each one has a standing agent that has followed it across every report it appeared\nin, and those agents have already answered. Your job is to **assemble** what they returned and\nto decide one thing of your own — what to act on first.\n\n## Setup\n\nBoth the gathering and the round of agents are **separate, deterministic steps**.\n\n1. `run.sh` has already produced `data.json` in your run directory.\n2. Run `sh $ROOT/issue-round.sh <run directory>`. It visits every item's agent in turn and\n   writes `contributions.json` beside `data.json`. It takes a few minutes per item; let it\n   finish.\n3. Read `contributions.json`. Each entry has a `report` object: a finished item, its facts\n   already filled in from the data and its judgement written by that item's own agent.\n4. Assemble `report.json` from those objects (see **Output Format**).\n\n### What \"assemble\" means\n\n**Place each `report` object in its group exactly as it is.** Do not rewrite an agent's\n`next_step`, `explanation`, `suggested_comment`, `last_activity` or `changed` — those are its\nwords about its own item, and it has context you do not: it has watched that ticket across\nevery previous report. Editing them would throw away the reason the agents exist.\n\nYou may:\n\n- **order** items within a group,\n- **choose the Top 3** across everything — this is your judgement, made after everyone has\n  reported,\n- **write the reminder line and counts**,\n- **note a dispute**: an entry whose `class_dispute` is non-empty means that agent believes its\n  computed class is wrong. Leave the class as computed and carry the dispute through, so a\n  human can see the disagreement.\n\nAn entry with `\"ok\": false` is an agent that did not report. Include the item with the facts\nthat are known, `next_step` null, and say plainly in its `explanation` that its agent did not\nreport today and **why** — quote the entry's `error` rather than paraphrasing it, because the\nreason is the actionable part. Do not invent a recommendation in its place.\n\nTreat a repeated non-answer as a fault worth seeing, not as routine: `\"busy\": true` is the one\nbenign case (somebody was mid-conversation with it, and it will report next time). Anything\nelse is the item's agent failing, and an item that has now gone several reports without one is\nworth saying so about in its explanation.\n\n> **Scope:** this report covers **Jira active queues** and **recent GitHub community issues**.\n> **Dependabot is out of scope** — it is handled by its own separate process. The aged\n> backlogs (Jira To Do / escalations, GitHub issues >30d, old questions) are handled by the\n> `jira-issues-development` process — do not list or action them here.\n\n## Core principle: \"Who has the ball?\"\n\nEvery item is classified by who owes the next move. The job of interrupt duty is to **hand\nthe ball back**. Unlike a parked/FYI list, **every item that appears in this report gets a\nrecommendation** — even when the right move today is \"wait, but optionally nudge.\"\n\n| Class | Meaning | Recommendation style |\n|---|---|---|\n| `ACT_NOW` | Ball is ours — untriaged, 0 comments, or the reporter's reply is the **last comment** | A concrete next step we owe now |\n| `FOLLOW_UP` | We replied last, now **idle ≥ 14 days** | Nudge or close-as-no-response |\n| `WAITING` | We replied last, **< 14 days** ago | \"Too soon for a nudge — optionally send a brief status request\" (still give the draft) |\n| `TRACKED` | Has an owner/assignee or a linked PR/issue moving | Confirm the link is live / monitor |\n\nDetermine the class for each item using the precomputed fields. **Apply top-to-bottom — first\nmatch wins:**\n\n- **GitHub issues:**\n  1. `tracked: true` (has assignee or a linked PR with state OPEN/MERGED) → `TRACKED`.\n     Check `linked_prs` for the PR state — if OPEN, recommend `TRACK PR`; if MERGED, verify\n     the fix landed and recommend `CLOSE` or monitor.\n  2. `ball: \"ours\"` → `ACT_NOW`.\n  3. `ball: \"reporter\"` + `idle_days >= 14` → `FOLLOW_UP`.\n  4. `ball: \"reporter\"` + `idle_days < 14` → `WAITING`.\n  - **Daily window = `age_days <= 30`.** The gather already applies it: everything in\n    `github.external_issues.issues` is inside the window. Older issues belong to the cleanup\n    processes (see Scope above); do not go looking for them.\n  - `github.questions.issues` holds the `kind/question` issues — they are already separated\n    out, and they go in the Open Questions section rather than the issues section.\n- **Jira tickets:** cover the three **active** queues — **New** (`new_bugs`), **In Triage**\n  (`in_triage`), and **Waiting for Reporter** (`waiting_reporter`, tickets explicitly in the\n  Jira \"Waiting for Reporter\" status). Each maps to a report group of the same name. Within a\n  group, refine the class from the last comment's author and idle time:\n  - Last comment from the reporter/external, or no comments → `ACT_NOW` (we owe the move).\n  - We (a team member) commented last, or status is Waiting for Reporter → `FOLLOW_UP` if\n    `idle_days >= 14` (nudge), else `WAITING` (too soon — still recommend an optional status\n    request).\n  - Assigned + a GH issue/PR moving → `TRACKED`.\n  - Use `last_comment_author`, `last_comment_at`, `idle_days` and `reporter` to decide who\n    spoke last. `reporter` is who filed the ticket; a `last_comment_author` who is not the\n    reporter and looks like a SUSE/Rancher engineer is us.\n  - The **To Do / escalations backlog** is out of scope — handled by `jira-issues-development`.\n\n### When is a Jira ticket ready for a GitHub issue?\n\nA `rancher/dashboard` GitHub issue is a **public, committed, tracked** work item — not a triage\nstep. **Do not recommend `NEEDS GH ISSUE` by default just because no GH link exists.** Only\nrecommend it when the ticket is *ready* — all four hold:\n\n1. **Confirmed dashboard/UI problem** — the root cause/fix lives in `rancher/dashboard`, not\n   backend or another team (Frameworks, Terraform/provisioning, Harvester). An internal note\n   pulling in another team, or a `needs-triage` label, means ownership isn't confirmed yet.\n2. **Reproducible or precisely scoped** — concrete repro steps or a clear spec; ideally\n   reproduced on a current release.\n3. **Triaged** — `needs-triage` cleared; kind (bug/enhancement) and priority understood.\n4. **Publicly describable** — can be written without customer-confidential details (the repo\n   is public; Jira holds the private context).\n\nIf **any** of these fail, the next step is **`TRIAGE`** (investigate / reproduce / confirm\nownership), **not** `NEEDS GH ISSUE`. Say which gate is missing (e.g. \"still `needs-triage`\nand the last note points at Terraform — confirm it's a UI bug and reproduce before opening a\npublic issue\"). `NEEDS GH ISSUE` is earned *after* triage, not in place of it.\n\n## Report structure\n\n### 1. Today's Reminder\nOne scannable line: counts per category, e.g.\n`Jira: 3 New · 2 In Triage · 4 Waiting for Reporter · GitHub: 5 new (≤30d) · 2 questions`.\nThen the **Top 3** most urgent items across everything (highest priority / oldest idle /\nunanswered).\n\n### 2. Jira — Active Tickets\n\n**Show every ticket** in the three queues, grouped into three sub-sections. None are hidden —\neven a ticket with no action due today appears. Each one is already written by its own agent;\nplace it in the right group.\n\n- **NEW** (`new_bugs`) — untriaged. We owe the first move: usually **`TRIAGE`** (reproduce,\n  confirm it's a UI issue), and only `NEEDS GH ISSUE` once the readiness gate above is met.\n- **IN TRIAGE** (`in_triage`) — being triaged. We owe a triage decision.\n- **WAITING FOR REPORTER** (`waiting_reporter`) — tickets in the Jira \"Waiting for Reporter\"\n  status. **Show every one**, even with no action due: give the last reply date and a\n  recommendation — `NUDGE` if idle ≥ 14d, else \"too soon — optionally send a status request\"\n  (with the draft). Never leave this group empty just because nothing is overdue.\n\nField details for each ticket:\n\n- `class` — one of `ACT_NOW` / `FOLLOW_UP` / `WAITING` / `TRACKED`.\n- `last_activity` — who commented last and when (e.g. \"reporter\", 3 / \"us\", 21) plus a short\n  `context` sentence. This is the *why* behind the recommendation.\n- `github_issue` — the existing GH link if the ticket has one, otherwise `null`.\n- `next_step.verb` — always exactly one: `TRIAGE` (investigate/reproduce/confirm ownership —\n  the default for an untriaged ticket), `NEEDS GH ISSUE` (only once the readiness gate is met),\n  `TRACK ISSUE`, `TRACK PR`, `RESPOND`, `NEEDS INFO`, `CONFIRM OWNER`, `REASSIGN`, `CLOSE`,\n  `NUDGE`, `STATUS REQUEST`.\n- `next_step.explanation` — concrete: what to do and why.\n- `suggested_comment` — **always present**: a short, copy-pasteable draft written as the\n  interrupt duty engineer.\n  - For **TRIAGE**, the comment is a standard acknowledgment that we're picking it up and\n    investigating, not a list of questions for the reporter (use `NEEDS INFO` for that).\n    Template: *\"Thank you for the bug report, we've moved this to In Triage and an engineer\n    will be taking a look to try and reproduce the bug. We'll update you soon and let you know\n    if further information is required.\"*\n  - For **WAITING < 14d**, still recommend something: *\"Too soon for a nudge (we replied Nd\n    ago), but if you want movement you could post a brief status request\"* — and give that draft.\n- `quick_action` — only for `NEEDS GH ISSUE`: a Create-issue link using the right template —\n  bug → `?template=bug_report.md`; enhancement/UX → `?template=feature_request.md`;\n  other → blank issue; always `&title=[SURE-XXXX]+TITLE` (URL-encoded). `null` otherwise.\n\n### 3. GitHub — Community Issues (New ≤30d)\n\n**Show every** issue in `github.external_issues.issues` (newest first), each with its own\nconcrete action **and a suggested comment**. Include both ball-ours issues AND `tracked: true`\nissues (so the engineer sees their linked PRs are progressing).\n\n- `class` — `TRACKED` / `ACT_NOW` / `FOLLOW_UP` / `WAITING`.\n- `kind` — a short human label from the labels (e.g. \"bug\", \"enhancement\", \"bug (dashboard)\").\n- `next_step.verb` — `TRACK PR` (linked PR is open — monitor progress), `TRIAGE`, `RESPOND`,\n  `NEEDS INFO`, `CONFIRM OWNER`, `REASSIGN`, `RE-TRIAGE`, or `CLOSE`.\n- `suggested_comment` — **required** for `TRIAGE`, `RESPOND`, `NEEDS INFO`, `CONFIRM OWNER`;\n  optional (`null`) for `TRACK PR` — only if the PR is stale or needs a nudge. A short,\n  copy-pasteable draft, specific to *this* issue — not a generic group note. For a bug repro:\n  confirm you're reproducing on the current release. For an enhancement: acknowledge and tag\n  `kind/enhancement`. For info gaps: ask the precise question that unblocks triage.\n\n### 4. GitHub — Open Questions (≤30d)\n\nEverything in `github.questions.issues`. For each: `next_step.verb` is `RESPOND` (answer it) or\n`NEEDS INFO` (ask for specifics), and `suggested_comment` is a short answer or the specific\nquestion to ask — specific to the issue. Questions are quick wins — answering closes the loop.\n\n## Output Format\n\nWrite **`report.json`** in the run directory — a single JSON document, nothing else in the\nfile: no markdown fence, no commentary before or after. It must parse with `JSON.parse`.\n\n```jsonc\n{\n  \"report_date\": \"YYYY-MM-DD\",          // from data.json's report_date\n  \"reminder\": {\n    \"line\": \"Jira: 0 New · 2 In Triage · 4 Waiting for Reporter · GitHub: 5 new (≤30d) · 0 questions\",\n    \"counts\": {\n      \"jira_new\": 0, \"jira_in_triage\": 2, \"jira_waiting_reporter\": 4,\n      \"github_new\": 5, \"github_questions\": 0\n    }\n  },\n  \"top3\": [\n    {\n      \"rank\": 1,\n      \"kind\": \"jira\",                   // \"jira\" | \"github\"\n      \"ref\": \"SURE-12028\",              // \"SURE-XXXX\" for Jira, \"#18669\" for GitHub\n      \"url\": \"https://...\",\n      \"title\": \"short title\",\n      \"class\": \"ACT_NOW\",\n      \"meta\": \"High · In Triage · 0d\",  // one short line of context\n      \"why\": \"One or two sentences on why this is the most urgent thing today.\"\n    }\n  ],\n  \"jira\": {\n    \"new\": [ /* JiraItem */ ],\n    \"in_triage\": [ /* JiraItem */ ],\n    \"waiting_reporter\": [ /* JiraItem */ ]\n  },\n  \"github\": {\n    \"issues\": [ /* GitHubItem */ ],\n    \"questions\": [ /* QuestionItem */ ]\n  }\n}\n```\n\n`JiraItem`:\n\n```jsonc\n{\n  \"key\": \"SURE-12028\",\n  \"url\": \"https://jira.suse.com/browse/SURE-12028\",\n  \"title\": \"Etcd snapshot restore on an Elemental cluster leaves a blank cluster\",\n  \"class\": \"ACT_NOW\",\n  \"priority\": \"High\",\n  \"age_days\": 0,\n  \"assignee\": \"Caio Torres\",            // or null\n  \"github_issue\": { \"label\": \"rancher/dashboard#9067\", \"url\": \"https://...\" },  // or null\n  \"last_activity\": { \"who\": \"reporter\", \"days_ago\": 2, \"context\": \"short sentence\" },\n  \"next_step\": { \"verb\": \"TRIAGE\", \"explanation\": \"concrete explanation\" },\n  \"suggested_comment\": \"copy-pasteable draft\",\n  \"quick_action\": { \"label\": \"Create GitHub issue\", \"url\": \"https://...\" }       // or null\n}\n```\n\n`GitHubItem`:\n\n```jsonc\n{\n  \"number\": 18981,\n  \"url\": \"https://github.com/rancher/dashboard/issues/18981\",\n  \"title\": \"short title\",\n  \"class\": \"TRACKED\",\n  \"age_days\": 5,\n  \"idle_days\": 5,\n  \"comments_count\": 1,\n  \"kind\": \"bug (clusterprovisioningv2)\",\n  \"linked_prs\": [ { \"number\": 18982, \"url\": \"https://...\", \"state\": \"OPEN\" } ],\n  \"next_step\": { \"verb\": \"TRACK PR\", \"explanation\": \"concrete explanation\" },\n  \"suggested_comment\": null\n}\n```\n\n`QuestionItem`:\n\n```jsonc\n{\n  \"number\": 18777,\n  \"url\": \"https://github.com/rancher/dashboard/issues/18777\",\n  \"title\": \"short title\",\n  \"age_days\": 12,\n  \"idle_days\": 9,\n  \"next_step\": { \"verb\": \"RESPOND\", \"explanation\": \"concrete explanation\" },\n  \"suggested_comment\": \"copy-pasteable draft\"\n}\n```\n\nRules for the JSON:\n\n- Every array key must be present, even when empty (`[]`). A missing group is a group the\n  report silently dropped.\n- `class` is one of `ACT_NOW`, `FOLLOW_UP`, `WAITING`, `TRACKED` — exactly those spellings.\n- `suggested_comment` is plain text, not markdown, and is shown to the engineer with a Copy\n  button — so write it as the message itself, with no surrounding quotes and no \"here's a\n  draft:\" preamble.\n- `explanation` and `why` are plain prose, one to three sentences. No markdown links — the URLs\n  are already their own fields.\n- Counts in `reminder.counts` must match the lengths of the arrays you produce.\n\n## Notes\n\n- A community issue with 0 comments is always `ACT_NOW` — someone external is waiting on a\n  first response.\n- **Never drop an active ticket for lack of an obvious action** — show it, explain why (last\n  activity), and recommend the best available move (often a gentle status request).\n- **Never recommend `NEEDS GH ISSUE` for an untriaged ticket.** A missing GitHub link is *not*\n  a reason to create one. Default to `TRIAGE`; only escalate to `NEEDS GH ISSUE` when the\n  readiness gate (confirmed UI · reproducible/scoped · triaged · publicly describable) is\n  fully met. When in doubt, `TRIAGE`. A `needs-triage` label, or a last comment pointing at\n  another team, by itself means the answer is `TRIAGE`.\n- When scanning for an existing GitHub issue on a Jira ticket, check `github_issue` first, then\n  the description/comments for `github.com/rancher/dashboard/issues/NNNN` or `.../pull/NNNN`.\n- When a ticket's thread references a fix in another team (backport, backend fix, duplicate),\n  check `linked_issues` for resolution. If a related fix has landed or the issue is confirmed\n  as another team's, recommend `REASSIGN` or `CLOSE` rather than continuing to wait.\n",
  "gather.mjs": "#!/usr/bin/env node\n// Gather the day's interrupt-duty data: the three active Jira queues and the recent\n// rancher/dashboard community issues, as one JSON file for the report to analyse.\n//\n// Deliberately dependency-free and shell-free. This runs inside the agent pod, which is a\n// stock `node:24` with no `jq` and no `gh` in it, so the pipeline the team runs on a laptop\n// (scripts/gather-all-data.sh) is re-expressed here in the one runtime the pod is guaranteed\n// to have. The derived fields - age, idle, who has the ball, whether an issue is tracked -\n// keep the names and the rules the report prompt reads them by, because the prompt is shared\n// with that pipeline and a renamed field is a report that silently loses a section.\n//\n// Credentials come from the environment, never from a command line: this is exec'd in a pod\n// where `ps` is readable, and a token in argv is a token on display.\n\nimport { readFileSync, writeFileSync } from 'node:fs';\n\nconst JIRA_BASE = process.env.JIRA_BASE_URL || 'https://jira.suse.com';\nconst REPO_OWNER = process.env.GH_OWNER || 'rancher';\nconst REPO_NAME = process.env.GH_REPO || 'dashboard';\nconst OUT = process.env.OUT || './data.json';\n\n// The daily window. The report covers Jira's active queues in full and only the last 30 days\n// of community issues; everything older belongs to the separate backlog processes.\nconst WINDOW_DAYS = Number(process.env.WINDOW_DAYS || 30);\n\n// The two tokens, read from a file named by CREDS_FILE rather than from the environment.\n//\n// A pod is a place where `ps` and `/proc/<pid>/environ` are readable, and this one is shared:\n// every conversation in it runs as the same user. A token on a command line or in an exported\n// variable is a token every pane in the pod can read for as long as the process lives. The file\n// is written 0600 by the extension, read here once, and removed by publish.sh when the run ends.\nfunction credentials() {\n  const file = process.env.CREDS_FILE;\n\n  if (!file) {\n    return { JIRA_PAT: process.env.JIRA_PAT || '', GH_TOKEN: process.env.GH_TOKEN || '' };\n  }\n\n  try {\n    return JSON.parse(readFileSync(file, 'utf8'));\n  } catch (e) {\n    fail(`could not read the credentials at ${ file }: ${ e?.message || e }`);\n  }\n}\n\nconst TEAM = 'UI';\n\nfunction fail(message) {\n  process.stderr.write(`gather: ${ message }\\n`);\n  process.exit(1);\n}\n\nconst { JIRA_PAT, GH_TOKEN } = credentials();\n\nif (!JIRA_PAT) {\n  fail('JIRA_PAT is not set. The three Jira queues cannot be read without it.');\n}\nif (!GH_TOKEN) {\n  fail('GH_TOKEN is not set. The community issues cannot be read without it.');\n}\n\nconst now = Date.now();\n\n/** Whole days between an ISO timestamp and now, floored - the unit every age in the report is in. */\nfunction daysSince(iso) {\n  if (!iso) {\n    return null;\n  }\n\n  // Jira stamps offsets without a colon (2026-09-02T11:20:31.000+0000), which Date rejects on\n  // some runtimes; normalise to the form it always accepts.\n  const normalised = String(iso).replace(/([+-]\\d{2})(\\d{2})$/, '$1:$2');\n  const then = Date.parse(normalised);\n\n  return Number.isNaN(then) ? null : Math.floor((now - then) / 86400000);\n}\n\nasync function request(url, init, what) {\n  let resp;\n\n  try {\n    resp = await fetch(url, init);\n  } catch (e) {\n    throw new Error(`${ what }: ${ e?.message || e }`, { cause: e });\n  }\n\n  const text = await resp.text();\n\n  if (!resp.ok) {\n    // The body is where an expired PAT actually says so, but it can be an HTML login page -\n    // so it is trimmed rather than printed whole.\n    const detail = text.slice(0, 300).replace(/\\s+/g, ' ').trim();\n\n    throw new Error(`${ what }: HTTP ${ resp.status }${ detail ? ` - ${ detail }` : '' }`);\n  }\n\n  try {\n    return JSON.parse(text);\n  } catch {\n    throw new Error(`${ what }: the answer was not JSON`);\n  }\n}\n\n// ── Jira ───────────────────────────────────────────────────────────────────────────────────\n\nconst JIRA_FIELDS = [\n  'key', 'summary', 'status', 'issuetype', 'assignee', 'priority', 'created', 'updated',\n  'reporter', 'description', 'comment', 'components', 'labels', 'issuelinks', 'resolution',\n  'versions', 'customfield_21300', 'customfield_23900', 'customfield_23901', 'customfield_24000',\n];\n\nasync function queryJira(jql) {\n  const body = await request(`${ JIRA_BASE }/rest/api/2/search`, {\n    method:  'POST',\n    headers: {\n      Authorization:  `Bearer ${ JIRA_PAT }`,\n      'Content-Type': 'application/json',\n      Accept:         'application/json',\n    },\n    body: JSON.stringify({ jql, maxResults: 100, fields: JIRA_FIELDS }),\n  }, 'Jira search');\n\n  return body.issues || [];\n}\n\n/** The multi-select custom fields come back as objects; the report only ever wants their values. */\nfunction values(field) {\n  return (field || []).map((entry) => entry?.value).filter(Boolean);\n}\n\nfunction normaliseJira(issues) {\n  return issues.map((issue) => {\n    const f = issue.fields || {};\n    const comments = f.comment?.comments || [];\n    const last = comments[comments.length - 1] || null;\n\n    // Who said what last, told apart. One \"idle\" number cannot answer both \"how long since we\n    // replied\" and \"how long has the reporter been quiet\", and the report needs both: the\n    // nudge rule is about the first, and whether a reporter has gone silent is the second.\n    //\n    // Measured on SURE-11767: the reporter last spoke on 27 July, we replied on 28 July, we\n    // nudged on 17 September. A single idle stamp read 0 that day, so a ticket whose reporter\n    // had been silent for 52 days reported as \"too soon for a nudge\" - and every nudge after\n    // that would reset it again. The harder we chased, the fresher it looked.\n    const reporterName = f.reporter?.displayName || null;\n    const byReporter = comments.filter((c) => (c.author?.displayName || null) === reporterName);\n    const byUs = comments.filter((c) => (c.author?.displayName || null) !== reporterName);\n    const lastOurs = byUs[byUs.length - 1] || null;\n    const lastTheirs = byReporter[byReporter.length - 1] || null;\n\n    return {\n      key:         issue.key,\n      url:         `${ JIRA_BASE }/browse/${ issue.key }`,\n      summary:     f.summary,\n      status:      f.status?.name || null,\n      type:        f.issuetype?.name || null,\n      priority:    f.priority?.name || null,\n      assignee:    f.assignee?.displayName || null,\n      reporter:    f.reporter?.displayName || null,\n      created:     f.created,\n      updated:     f.updated,\n      age_days:    daysSince(f.created),\n      // Since WE replied - which is what the nudge rule has always said it measures. It used\n      // to be the last comment by anybody, so our own nudge reset it.\n      idle_days:   daysSince(lastOurs?.created || last?.created || f.updated),\n      // Since the REPORTER last said anything, counted from the ticket if they never have.\n      // This is the one that says whether they have gone quiet, and nothing we do resets it.\n      reporter_silent_days: daysSince(lastTheirs?.created || f.created),\n      description: f.description || '',\n      // The last three, which is what the prompt reads to decide who owes the next move. The\n      // whole thread would be most of this file for no gain.\n      comments:    comments.slice(-3).map((c) => ({\n        author:  c.author?.displayName || null,\n        created: c.created,\n        body:    c.body || '',\n      })),\n      comments_count:      comments.length,\n      last_comment_author: last?.author?.displayName || null,\n      last_comment_at:     last?.created || null,\n      labels:              f.labels || [],\n      components:          (f.components || []).map((c) => c.name),\n      affects_versions:    (f.versions || []).map((v) => v.name),\n      github_issue:        f.customfield_21300 ?? null,\n      rancher_team:        values(f.customfield_23900),\n      account_name:        values(f.customfield_23901),\n      support_cases:       f.customfield_24000 || [],\n      linked_issues:       (f.issuelinks || []).map((link) => ({\n        type:    link.type?.name || null,\n        key:     link.inwardIssue?.key || link.outwardIssue?.key || null,\n        summary: link.inwardIssue?.fields?.summary || link.outwardIssue?.fields?.summary || null,\n      })).filter((l) => l.key),\n    };\n  });\n}\n\n// The three ACTIVE queues, and only those. The To Do / escalation backlog belongs to the\n// jira-issues-development process and the report explicitly does not cover it.\nconst JIRA_QUERIES = {\n  new_bugs:         `project = SURE AND type = Bug AND resolution = Unresolved AND \"Rancher Team\" = ${ TEAM } AND status = New ORDER BY priority`,\n  in_triage:        `project = SURE AND type = Bug AND resolution = Unresolved AND \"Rancher Team\" = ${ TEAM } AND (Status = \"In Triage\") AND (component IS EMPTY OR component not in (Harvester)) ORDER BY priority, created ASC`,\n  waiting_reporter: `project = SURE AND type = Bug AND resolution = Unresolved AND \"Rancher Team\" = ${ TEAM } AND status = \"Waiting for Reporter\" ORDER BY priority, created ASC`,\n};\n\n// ── GitHub ─────────────────────────────────────────────────────────────────────────────────\n\nconst INTERNAL = new Set(['MEMBER', 'OWNER', 'COLLABORATOR']);\n\nconst ISSUES_QUERY = `\nquery($owner: String!, $name: String!, $cursor: String) {\n  repository(owner: $owner, name: $name) {\n    issues(states: OPEN, first: 100, after: $cursor, orderBy: {field: CREATED_AT, direction: DESC}) {\n      pageInfo { hasNextPage endCursor }\n      nodes {\n        number title url createdAt updatedAt authorAssociation\n        author { login __typename }\n        assignees { totalCount }\n        comments(last: 20) { totalCount nodes { authorAssociation createdAt author { login __typename } } }\n        labels(first: 20) { nodes { name } }\n        timelineItems(itemTypes: [CROSS_REFERENCED_EVENT], last: 10) {\n          nodes { ... on CrossReferencedEvent { source { ... on PullRequest { number state url } } } }\n        }\n        body\n      }\n    }\n  }\n}`;\n\nasync function graphql(query, variables) {\n  const body = await request('https://api.github.com/graphql', {\n    method:  'POST',\n    headers: {\n      Authorization:  `Bearer ${ GH_TOKEN }`,\n      'Content-Type': 'application/json',\n      Accept:         'application/json',\n      'User-Agent':   'interrupt-duty-reports-console',\n    },\n    body: JSON.stringify({ query, variables }),\n  }, 'GitHub GraphQL');\n\n  if (body.errors?.length) {\n    throw new Error(`GitHub GraphQL: ${ body.errors.map((e) => e.message).join('; ') }`);\n  }\n\n  return body.data;\n}\n\n/**\n * Every open issue created inside the window, newest first.\n *\n * Ordered by creation and stopped at the cutoff rather than filtered after the fact: the repo\n * has thousands of open issues and the report wants the last thirty days of them. Ordering by\n * update instead - which the laptop pipeline does, because it wants the whole set - would mean\n * no page could ever be the last one.\n *\n * The listing rather than the search index, because the index lags by minutes and a\n * minutes-old issue with no comments on it is precisely the ACT NOW case the report exists to\n * surface.\n */\nasync function fetchRecentIssues(cutoffMs) {\n  const nodes = [];\n  let cursor = null;\n\n  for (let page = 0; page < 30; page++) {\n    const data = await graphql(ISSUES_QUERY, { owner: REPO_OWNER, name: REPO_NAME, cursor });\n    const conn = data?.repository?.issues;\n\n    if (!conn) {\n      break;\n    }\n\n    let reachedCutoff = false;\n\n    for (const node of conn.nodes || []) {\n      if (Date.parse(node.createdAt) < cutoffMs) {\n        reachedCutoff = true;\n        break;\n      }\n      nodes.push(node);\n    }\n\n    if (reachedCutoff || !conn.pageInfo?.hasNextPage) {\n      break;\n    }\n\n    cursor = conn.pageInfo.endCursor;\n  }\n\n  return nodes;\n}\n\nfunction normaliseIssue(node) {\n  const commentNodes = node.comments?.nodes || [];\n  const lastComment = commentNodes[commentNodes.length - 1] || null;\n\n  // Told apart, the same way the Jira side does it. A bot is automation, not either side.\n  const human = commentNodes.filter((c) => c.author?.__typename !== 'Bot');\n  const ours = human.filter((c) => INTERNAL.has(c.authorAssociation));\n  const theirs = human.filter((c) => !INTERNAL.has(c.authorAssociation));\n  const lastOurs = ours[ours.length - 1] || null;\n  const lastTheirs = theirs[theirs.length - 1] || null;\n  const labels = (node.labels?.nodes || []).map((l) => l.name);\n  const linkedPrs = (node.timelineItems?.nodes || [])\n    .map((t) => t.source)\n    .filter((s) => s && typeof s.number === 'number')\n    .map((s) => ({ number: s.number, state: s.state, url: s.url }));\n  const hasLinkedPr = linkedPrs.some((pr) => pr.state === 'OPEN' || pr.state === 'MERGED');\n  const hasAssignee = (node.assignees?.totalCount || 0) > 0;\n\n  // Who owes the next move. No comments at all is ours by definition - somebody external is\n  // waiting on a first response. A bot's comment is automation, not an answer, so it leaves\n  // the ball where it was; anything from a member/owner/collaborator hands it to the reporter.\n  let ball = 'ours';\n\n  if ((node.comments?.totalCount || 0) > 0 && lastComment) {\n    if (lastComment.author?.__typename !== 'Bot' && INTERNAL.has(lastComment.authorAssociation)) {\n      ball = 'reporter';\n    }\n  }\n\n  return {\n    number:                   node.number,\n    url:                      node.url,\n    title:                    node.title,\n    author:                   node.author?.login || null,\n    author_association:       node.authorAssociation,\n    created_at:               node.createdAt,\n    updated_at:               node.updatedAt,\n    age_days:                 daysSince(node.createdAt),\n    // Since WE replied. It used to be `updatedAt`, which moves when anybody adds a label or\n    // assigns the issue - so an issue with no conversation at all could look active, and the\n    // comment above the Jira version said a field edit is not a reply while this one counted\n    // exactly that. Falls back to the issue's own stamps when we have never replied.\n    idle_days:                daysSince(lastOurs?.createdAt || node.createdAt),\n    // Since the reporter or any outside voice last said anything. Nothing we do resets it.\n    reporter_silent_days:     daysSince(lastTheirs?.createdAt || node.createdAt),\n    comments_count:           node.comments?.totalCount || 0,\n    last_comment_association: lastComment?.authorAssociation || null,\n    last_comment_author:      lastComment?.author?.login || null,\n    last_comment_at:          lastComment?.createdAt || null,\n    has_assignee:             hasAssignee,\n    labels,\n    is_question:              labels.includes('kind/question'),\n    linked_prs:               linkedPrs,\n    has_linked_pr:            hasLinkedPr,\n    ball,\n    tracked:                  hasAssignee || hasLinkedPr,\n    body:                     (node.body || '').slice(0, 2000),\n  };\n}\n\n/** Community, not us and not automation - the set the report calls \"external\". */\nfunction isCommunity(node) {\n  return !INTERNAL.has(node.authorAssociation) && node.author?.__typename !== 'Bot';\n}\n\n// ── Run ────────────────────────────────────────────────────────────────────────────────────\n\nasync function main() {\n  const reportDate = new Date(now).toISOString().slice(0, 10);\n  const cutoffMs = now - (WINDOW_DAYS * 86400000);\n\n  process.stderr.write('=== Gathering Jira data ===\\n');\n\n  const jira = {};\n\n  for (const [name, jql] of Object.entries(JIRA_QUERIES)) {\n    process.stderr.write(`  ${ name }...\\n`);\n    const issues = normaliseJira(await queryJira(jql));\n\n    jira[name] = { count: issues.length, issues };\n  }\n\n  process.stderr.write('=== Gathering GitHub data ===\\n');\n  process.stderr.write(`  community issues created in the last ${ WINDOW_DAYS }d...\\n`);\n\n  const raw = await fetchRecentIssues(cutoffMs);\n  const issues = raw.filter(isCommunity).map(normaliseIssue);\n\n  // Questions are answered in their own section of the report, so they are separated here\n  // rather than by a filter the prompt has to remember to apply.\n  const questions = issues.filter((i) => i.is_question);\n  const needsAttention = issues.filter((i) => !i.is_question);\n\n  const output = {\n    report_date:  reportDate,\n    generated_at: new Date(now).toISOString(),\n    window_days:  WINDOW_DAYS,\n    source:       {\n      jira_base_url: JIRA_BASE,\n      github_repo:   `${ REPO_OWNER }/${ REPO_NAME }`,\n    },\n    jira,\n    github: {\n      external_issues: {\n        count:      needsAttention.length,\n        act_now:    needsAttention.filter((i) => i.ball === 'ours' && !i.tracked).length,\n        follow_up:  needsAttention.filter((i) => i.ball === 'reporter' && i.idle_days >= 14 && !i.tracked).length,\n        waiting:    needsAttention.filter((i) => i.ball === 'reporter' && i.idle_days < 14 && !i.tracked).length,\n        tracked:    needsAttention.filter((i) => i.tracked).length,\n        issues:     needsAttention,\n      },\n      questions: { count: questions.length, issues: questions },\n    },\n  };\n\n  writeFileSync(OUT, `${ JSON.stringify(output, null, 2) }\\n`);\n\n  process.stderr.write('=== Done ===\\n');\n  process.stderr.write(`Data written to ${ OUT }\\n`);\n  process.stderr.write(`  Jira: ${ jira.new_bugs.count } new, ${ jira.in_triage.count } in triage, ${ jira.waiting_reporter.count } waiting for reporter\\n`);\n  process.stderr.write(`  GitHub: ${ needsAttention.length } community issues (<=${ WINDOW_DAYS }d), ${ questions.length } questions\\n`);\n}\n\nmain().catch((e) => fail(e?.message || String(e)));\n",
  "issue-agent.sh": "#!/bin/sh\n# One long-lived agent per issue, resumed across reports.\n#\n# A report used to be one agent doing everything, so what it learned about a ticket died with\n# the run and the next day's report started from nothing. An issue outlives a report: the same\n# SURE-1234 comes back tomorrow with one more comment on it, and the useful question is \"what\n# changed since you last looked\", which only something that looked before can answer.\n#\n# So each issue gets a claude conversation of its own that is RESUMED rather than restarted.\n# What it knew yesterday it still knows today, in its own words, without a summary having to\n# carry it.\n#\n#   issue-agent.sh ask   <key> <file> [who]    # find or create, resume, print the answer\n#   issue-agent.sh id    <key>                 # the claude session uuid, or nothing\n#   issue-agent.sh dir   <key>                 # where it lives\n#   issue-agent.sh busy  <key>                 # busy / stale <pid> / free\n#   issue-agent.sh reap  <key>                 # kill an abandoned chat holding this agent\n#   issue-agent.sh end   <key>                 # the ticket is closed; forget it\n#   issue-agent.sh list                        # every issue with an agent\n#\n# A DIRECTORY PER ISSUE, which is the whole trick. claude keeps one transcript per working\n# directory under ~/.claude/projects/<dir with slashes as dashes>, so an issue's directory holds\n# exactly one conversation and \"which transcript is this agent's\" has a single answer. The\n# agent panel's own panes share one directory and have to guess by watching which file appears -\n# see the comment in claude-session.sh about two panes starting at the same moment. Here there\n# is nothing to guess.\nset -e\n\nROOT=${ISSUE_AGENT_ROOT:-/workspace/idr-issues}\nCLAUDE=${CLAUDE_BIN:-/workspace/.home/.local/bin/claude}\n\n# claude refuses --dangerously-skip-permissions as root, and the pod's exec lands as root.\n[ \"$(id -u)\" = \"0\" ] && exec setpriv --reuid=1000 --regid=1000 --init-groups \\\n  /usr/bin/env HOME=/workspace/.home ISSUE_AGENT_ROOT=\"$ROOT\" CLAUDE_BIN=\"$CLAUDE\" \\\n  /bin/sh \"$0\" \"$@\"\n\nexport HOME=${HOME:-/workspace/.home}\n\n# An issue key as a directory name. Keys are `PROJ-123`, but a key from a feed is not to be\n# trusted with a path: anything that is not a letter, digit or hyphen becomes a hyphen.\nslug() {\n  printf '%s' \"$1\" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9-]\\{1,\\}/-/g; s/^-*//; s/-*$//' | cut -c1-60\n}\n\ndir_for() { echo \"$ROOT/$(slug \"$1\")\"; }\n\n# The transcript in a directory, which is this issue's conversation. Exactly one, by construction.\ntranscript_in() {\n  ls \"$HOME/.claude/projects/$(printf '%s' \"$1\" | tr '/' '-')\"/*.jsonl 2>/dev/null | head -1\n}\n\n# How long a chat may sit idle before the round stops treating it as a person mid-conversation.\n# Minutes, not days: standing down is meant to yield to somebody typing, and an abandoned chat\n# that outranks the round forever is how an item silently stops being reported at all.\nIDLE_LIMIT=${ISSUE_CHAT_IDLE_LIMIT:-900}\n\n# The pid of a claude working in this directory, if there is one.\n#\n# Only visible as the owner: this pod runs the exec as root WITHOUT CAP_DAC_READ_SEARCH, so\n# /proc/<pid>/cwd of a process owned by node reads back EMPTY rather than erroring - and an\n# empty string compares equal to another empty string. Hence the re-exec to uid 1000 at the top\n# of this script, and hence the guard here that a blank cwd never matches.\nblocker_in() {\n  _d=$(readlink -f \"$1\" 2>/dev/null)\n  [ -n \"$_d\" ] || return 0\n\n  for _pid in $(pgrep -f \"$CLAUDE\" 2>/dev/null); do\n    _cwd=$(readlink -f \"/proc/$_pid/cwd\" 2>/dev/null)\n    [ -n \"$_cwd\" ] && [ \"$_cwd\" = \"$_d\" ] && { echo \"$_pid\"; return 0; }\n  done\n}\n\n# Seconds since anything was said in this conversation.\n#\n# The transcript's mtime, NOT the process's age or its parent. A live conversation appends to\n# its JSONL on every turn, so mtime is the one thing that actually tracks whether a person is\n# there. Age says nothing - a pane open for three days may have somebody in it or nobody. And\n# PPID says nothing either: a process exec'd into this pod has PPID 0 whether it is live or\n# abandoned, which was measured rather than assumed.\nidle_seconds() {\n  _t=$(transcript_in \"$1\" || true)\n  [ -n \"$_t\" ] || { echo 999999; return 0; }\n  _m=$(stat -c %Y \"$_t\" 2>/dev/null) || { echo 999999; return 0; }\n  echo $(( $(date +%s) - _m ))\n}\n\ncmd=${1:?issue-agent.sh needs a command}\n\ncase \"$cmd\" in\n  id)\n    d=$(dir_for \"${2:?needs an issue key}\")\n    [ -s \"$d/session.id\" ] && cat \"$d/session.id\" || true\n    ;;\n\n  dir)\n    dir_for \"${2:?needs an issue key}\"\n    ;;\n\n  busy)\n    # Is somebody talking to this agent right now?\n    #\n    # One transcript, one writer. The console can open a chat on an issue and the nightly round\n    # resumes the same conversation, and two claudes appending to one JSONL is how a\n    # conversation gets corrupted rather than merged. A chat is a person waiting, so the round\n    # is the one that stands down.\n    #\n    # But only while somebody is actually there. \"A claude exists in this directory\" was the\n    # old test, and a terminal pane closed in the browser leaves one running on an abandoned\n    # pty indefinitely - PPID 0, no reader, still holding the lock. One did, for four days, and\n    # the item it belonged to reported nothing the whole time while the report cheerfully said\n    # its chat was open. So presence is not the test; recent conversation is.\n    d=$(dir_for \"${2:?needs an issue key}\")\n    pid=$(blocker_in \"$d\")\n\n    if [ -z \"$pid\" ]; then\n      echo free\n    elif [ \"$(idle_seconds \"$d\")\" -lt \"$IDLE_LIMIT\" ]; then\n      echo busy\n    else\n      echo \"stale $pid\"\n    fi\n    ;;\n\n  reap)\n    # Kill an abandoned chat so its agent can work again.\n    #\n    # Only ever the stale case: a conversation with somebody in it is left alone, and the\n    # caller that wants it gone anyway (the person typing into the composer, who IS the only\n    # one who could be at the other end) says so with `force`.\n    d=$(dir_for \"${2:?needs an issue key}\")\n    pid=$(blocker_in \"$d\")\n\n    if [ -z \"$pid\" ]; then\n      echo \"issue-agent: nothing holding ${2}\"\n    elif [ \"${3:-}\" != \"force\" ] && [ \"$(idle_seconds \"$d\")\" -lt \"$IDLE_LIMIT\" ]; then\n      echo \"issue-agent: ${2} is in use, not reaping\" >&2\n      exit 3\n    else\n      kill \"$pid\" 2>/dev/null || true\n      sleep 1\n      kill -9 \"$pid\" 2>/dev/null || true\n      echo \"issue-agent: reaped $pid holding ${2}\"\n    fi\n    ;;\n\n  list)\n    for d in \"$ROOT\"/*/; do\n      [ -d \"$d\" ] || continue\n      k=$(cat \"$d/key\" 2>/dev/null || basename \"$d\")\n      printf '%s\\t%s\\t%s\\n' \"$k\" \"$(basename \"$d\")\" \"$(cat \"$d/session.id\" 2>/dev/null || echo -)\"\n    done\n    ;;\n\n  end)\n    # The ticket is closed, so the agent is too: the directory and the transcript both go. Kept\n    # until then rather than pruned by age - an issue quiet for a month is still the same issue.\n    d=$(dir_for \"${2:?needs an issue key}\")\n    t=$(transcript_in \"$d\" || true)\n    [ -n \"$t\" ] && rm -f \"$t\"\n    rm -rf \"$d\"\n    echo \"issue-agent: ended ${2}\"\n    ;;\n\n  ask)\n    KEY=${2:?needs an issue key}\n    FILE=${3:?needs a prompt file}\n    # WHO is asking, and it changes the answer to \"somebody else is here\".\n    #\n    #   round - the nightly pass. Yields to a person mid-conversation; that is the whole point\n    #           of the guard, and what it says will be in the transcript tomorrow anyway.\n    #   chat  - the person reading the report, typing into the item's composer. NEVER yields.\n    #\n    # The two used to share one path, so the composer inherited the round's stand-down and\n    # refused the person it was protecting: type a note, get back \"leaving it to whoever is\n    # talking to it\" - about yourself. A human waiting on an answer outranks every other\n    # caller, including a stale copy of their own earlier chat.\n    WHO=${4:-round}\n    [ -f \"$FILE\" ] || { echo \"issue-agent: no such prompt file: $FILE\" >&2; exit 2; }\n\n    d=$(dir_for \"$KEY\")\n    pid=$(blocker_in \"$d\")\n\n    if [ -n \"$pid\" ]; then\n      if [ \"$WHO\" = \"chat\" ]; then\n        # The person is here, so whatever else holds the transcript is either their own\n        # abandoned pane or nothing that should outrank them.\n        kill \"$pid\" 2>/dev/null || true\n        sleep 1\n        kill -9 \"$pid\" 2>/dev/null || true\n        echo \"issue-agent: took $KEY back from $pid\" >&2\n      elif [ \"$(idle_seconds \"$d\")\" -lt \"$IDLE_LIMIT\" ]; then\n        echo \"issue-agent: $KEY has its chat open; leaving it to whoever is talking to it\" >&2\n        exit 3\n      else\n        # Abandoned, not busy. Reap it and get on with the round - an item that reports\n        # nothing is worse than a pane nobody was sitting at.\n        kill \"$pid\" 2>/dev/null || true\n        sleep 1\n        kill -9 \"$pid\" 2>/dev/null || true\n        echo \"issue-agent: reaped abandoned chat $pid on $KEY (idle $(idle_seconds \"$d\")s)\" >&2\n      fi\n    fi\n\n    mkdir -p \"$d\"\n    printf '%s' \"$KEY\" > \"$d/key\"\n    cd \"$d\"\n\n    if [ -s \"$d/session.id\" ]; then\n      # Resume by name. The fallback is not \"start fresh silently\": a transcript that has gone\n      # means the memory has gone, and the caller should see a first-contact answer rather than\n      # believe it got a remembered one.\n      \"$CLAUDE\" --dangerously-skip-permissions --resume \"$(cat \"$d/session.id\")\" -p \"$(cat \"$FILE\")\" ||\n        { echo \"issue-agent: could not resume $KEY, starting fresh\" >&2; rm -f \"$d/session.id\"; \"$CLAUDE\" --dangerously-skip-permissions -p \"$(cat \"$FILE\")\"; }\n    else\n      \"$CLAUDE\" --dangerously-skip-permissions -p \"$(cat \"$FILE\")\"\n    fi\n\n    # Record the session AFTER the first run, when the transcript exists. One per directory, so\n    # there is nothing to disambiguate.\n    if [ ! -s \"$d/session.id\" ]; then\n      t=$(transcript_in \"$d\" || true)\n      [ -n \"$t\" ] && basename \"$t\" .jsonl > \"$d/session.id\"\n    fi\n    ;;\n\n  *)\n    echo \"issue-agent.sh: unknown command: $cmd\" >&2\n    exit 2\n    ;;\nesac\n",
  "issue-brief.md": "# Your standing brief\n\nYou are the agent for ONE item — a Jira ticket or a GitHub issue — and you keep it for as long\nas it is open. You are asked about it once per daily report. Read this brief once; you will be\ngiven it again only if you forget it.\n\nYour job each time: say what CHANGED since you last looked, and recommend the next move. You do\nnot write the report and you do not see anyone else's item. The reporter assembles what every\nagent returns and decides only what to act on first.\n\n## What you are given\n\nThe first time: the whole item. Every time after: only what is new — a status change, the\ncomments posted since you last looked, today's idle days. **You are the one holding the\nhistory**; that is why nobody sends it to you twice. If you genuinely cannot answer without\nsomething you were not given, say so in your answer rather than inventing it.\n\nYour item's **class** is computed from the data and handed to you. It is not your decision,\nbecause it is a lookup, not a judgement. Use it. If you think it is wrong, put one line in\n`class_dispute` saying why — do not quietly answer as if it were a different class.\n\n## Core principle: \"Who has the ball?\"\n\nEvery item is classified by who owes the next move. The job of interrupt duty is to **hand\nthe ball back**. Unlike a parked/FYI list, **every item that appears in this report gets a\nrecommendation** — even when the right move today is \"wait, but optionally nudge.\"\n\n| Class | Meaning | Recommendation style |\n|---|---|---|\n| `ACT_NOW` | Ball is ours — untriaged, 0 comments, or the reporter's reply is the **last comment** | A concrete next step we owe now |\n| `FOLLOW_UP` | We replied last, now **idle ≥ 14 days** | Nudge or close-as-no-response |\n| `WAITING` | We replied last, **< 14 days** ago | \"Too soon for a nudge — optionally send a brief status request\" (still give the draft) |\n| `TRACKED` | Has an owner/assignee or a linked PR/issue moving | Confirm the link is live / monitor |\n\nDetermine the class for each item using the precomputed fields. **Apply top-to-bottom — first\nmatch wins:**\n\n- **GitHub issues:**\n  1. `tracked: true` (has assignee or a linked PR with state OPEN/MERGED) → `TRACKED`.\n     Check `linked_prs` for the PR state — if OPEN, recommend `TRACK PR`; if MERGED, verify\n     the fix landed and recommend `CLOSE` or monitor.\n  2. `ball: \"ours\"` → `ACT_NOW`.\n  3. `ball: \"reporter\"` + `idle_days >= 14` → `FOLLOW_UP`.\n  4. `ball: \"reporter\"` + `idle_days < 14` → `WAITING`.\n  - **Daily window = `age_days <= 30`.** The gather already applies it: everything in\n    `github.external_issues.issues` is inside the window. Older issues belong to the cleanup\n    processes (see Scope above); do not go looking for them.\n  - `github.questions.issues` holds the `kind/question` issues — they are already separated\n    out, and they go in the Open Questions section rather than the issues section.\n- **Jira tickets:** cover the three **active** queues — **New** (`new_bugs`), **In Triage**\n  (`in_triage`), and **Waiting for Reporter** (`waiting_reporter`, tickets explicitly in the\n  Jira \"Waiting for Reporter\" status). Each maps to a report group of the same name. Within a\n  group, refine the class from the last comment's author and idle time:\n  - Last comment from the reporter/external, or no comments → `ACT_NOW` (we owe the move).\n  - We (a team member) commented last, or status is Waiting for Reporter → `FOLLOW_UP` if\n    `idle_days >= 14` (nudge), else `WAITING` (too soon — still recommend an optional status\n    request).\n  - Assigned + a GH issue/PR moving → `TRACKED`.\n  - Use `last_comment_author`, `last_comment_at`, `idle_days` and `reporter` to decide who\n    spoke last. `reporter` is who filed the ticket; a `last_comment_author` who is not the\n    reporter and looks like a SUSE/Rancher engineer is us.\n  - The **To Do / escalations backlog** is out of scope — handled by `jira-issues-development`.\n\n### When is a Jira ticket ready for a GitHub issue?\n\nA `rancher/dashboard` GitHub issue is a **public, committed, tracked** work item — not a triage\nstep. **Do not recommend `NEEDS GH ISSUE` by default just because no GH link exists.** Only\nrecommend it when the ticket is *ready* — all four hold:\n\n1. **Confirmed dashboard/UI problem** — the root cause/fix lives in `rancher/dashboard`, not\n   backend or another team (Frameworks, Terraform/provisioning, Harvester). An internal note\n   pulling in another team, or a `needs-triage` label, means ownership isn't confirmed yet.\n2. **Reproducible or precisely scoped** — concrete repro steps or a clear spec; ideally\n   reproduced on a current release.\n3. **Triaged** — `needs-triage` cleared; kind (bug/enhancement) and priority understood.\n4. **Publicly describable** — can be written without customer-confidential details (the repo\n   is public; Jira holds the private context).\n\nIf **any** of these fail, the next step is **`TRIAGE`** (investigate / reproduce / confirm\nownership), **not** `NEEDS GH ISSUE`. Say which gate is missing (e.g. \"still `needs-triage`\nand the last note points at Terraform — confirm it's a UI bug and reproduce before opening a\npublic issue\"). `NEEDS GH ISSUE` is earned *after* triage, not in place of it.\n\n## Length: say it once, and stop\n\n**This is the rule most easily lost here.** Until now one agent wrote every item in the report\nin a single sitting, and was brief because it had eight others to get through. You have one\nitem and a whole context to yourself, so that pressure is gone and nothing stops you writing\nan essay — except that the engineer reads twenty of these before their first coffee.\n\n- `next_step.explanation`: **one to three sentences.** Not four.\n- `suggested_comment`: **short** — the length of a message somebody would actually paste into\n  a ticket. A few sentences. If it has grown into paragraphs, it is a plan, not a comment.\n- `changed`: **one line.**\n\nBeing thorough in your own head is the point of you. Spending it on the reader is not.\n\n**This applies to what you carry forward, not only to what you write today.** You will often\nbe reusing a draft you wrote on an earlier day - that is the point of remembering - and a\ndraft written before this rule existed does not inherit it. Measured on the day this was\nadded: every explanation was rewritten and got shorter, while six of nine comments came back\nbyte-identical to the day before, still over length, because reusing them looked like the\nright thing to do. So: before you hand back anything you wrote previously, check it against\nthe budget above and shorten it if it is over. A remembered answer is not exempt from a rule\nthat arrived after it.\n\n## Two clocks, and the difference between them\n\n- `idle_days` — how long since **we** replied. This is what the nudge rule measures.\n- `reporter_silent_days` — how long since the **reporter** last said anything. Nothing we do\n  resets it.\n\nThey agree while a conversation is going and come apart when we are chasing somebody who has\nstopped answering. That gap is worth saying out loud: \"we nudged today, but the reporter has\nnot spoken in 52 days\" is a far more useful sentence than either number alone, and it is the\ncase where a ticket most needs a decision — keep chasing, or close as no-response.\n\nThis used to be one number measured from the last comment by anybody, so our own nudge reset\nit and a long-silent reporter looked freshly attended to. If you see the two far apart, say so.\n\n## The next step\n\n`next_step.verb` is exactly one of: `TRIAGE`, `NEEDS GH ISSUE`, `TRACK ISSUE`, `TRACK PR`,\n`RESPOND`, `NEEDS INFO`, `CONFIRM OWNER`, `REASSIGN`, `CLOSE`, `NUDGE`, `STATUS REQUEST`.\n\n`next_step.explanation` is concrete: what to do, and why, in one to three plain sentences. No\nmarkdown links — the URLs are already their own fields.\n\n## The suggested comment\n\nAlways write one for a Jira ticket, as the interrupt duty engineer: **a short**,\ncopy-pasteable draft. Plain text, no markdown, no surrounding quotes, no \"here is a draft\"\npreamble — it is copied straight into the ticket, so it has to read like something a person\ntyped, not like a briefing.\n\n- **TRIAGE** is an acknowledgement that we are picking it up, not a list of questions (use\n  `NEEDS INFO` for questions). Template: *\"Thank you for the bug report, we've moved this to In\n  Triage and an engineer will be taking a look to try and reproduce the bug. We'll update you\n  soon and let you know if further information is required.\"*\n- **WAITING under 14 days** still gets a recommendation: too soon to nudge, but offer a brief\n  status request — and write that draft.\n\nFor a GitHub issue `suggested_comment` may be null; for a question it is the reply you would\npost.\n\n## What changed\n\n`changed` is the one thing only you can write, because only you were here last time. One line.\n\"first look\" if this is the first. If nothing moved, say that plainly — \"nothing since the 3rd,\nstill waiting on the reporter\" is a useful sentence, and inventing movement is not.\n",
  "issue-prune.mjs": "#!/usr/bin/env node\n// End an agent when its item is finished with.\n//\n// An agent is a conversation that has followed one item across every report it appeared in, so\n// ending one throws away real memory. It is worth doing - a ticket closed in March should not\n// still have an agent in December - and it is worth doing carefully.\n//\n// ABSENT FROM TODAY IS NOT CLOSED. The gather returns the three active Jira queues and GitHub\n// issues inside a thirty-day window, so an item leaves it for reasons that have nothing to do\n// with being finished: a ticket moved to In Progress, an issue that aged past the window, a\n// status changed for an afternoon. Pruning on absence would delete the memory of exactly the\n// items whose history is worth most, and it would do it quietly.\n//\n// So absence is only the question. The answer comes from asking the tracker what the item's\n// state actually is, one request per absent item - a handful a day, against the same APIs the\n// gather already uses with the same credentials.\n//\n//   issue-prune.mjs <run-dir>          # end the agents whose items are closed\n//   DRY_RUN=1 issue-prune.mjs <dir>    # say what it would end, change nothing\nimport { readFileSync } from 'node:fs';\nimport { execFileSync } from 'node:child_process';\n\nconst DIR = process.argv[2];\nconst ROOT = process.env.ISSUE_SEED_ROOT || '/workspace/.interrupt-duty';\nconst JIRA_BASE = process.env.JIRA_BASE_URL || 'https://jira.suse.com';\nconst REPO_OWNER = process.env.GH_OWNER || 'rancher';\nconst REPO_NAME = process.env.GH_REPO || 'dashboard';\nconst DRY = !!process.env.DRY_RUN;\n\nif (!DIR) {\n  process.stderr.write('issue-prune: needs the run directory\\n');\n  process.exit(2);\n}\n\nconst creds = JSON.parse(readFileSync(`${ DIR }/creds.json`, 'utf8'));\nconst data = JSON.parse(readFileSync(`${ DIR }/data.json`, 'utf8'));\n\n/** Every key in today's report, in the spelling the agents are named by. */\nfunction todaysKeys() {\n  const keys = new Set();\n\n  for (const group of Object.values(data.jira || {})) {\n    for (const t of (Array.isArray(group) ? group : group?.issues || [])) {\n      keys.add(t.key);\n    }\n  }\n\n  for (const part of ['external_issues', 'questions']) {\n    for (const i of data.github?.[part]?.issues || []) {\n      keys.add(`#${ i.number }`);\n    }\n  }\n\n  return keys;\n}\n\nfunction agents() {\n  const out = execFileSync('/bin/sh', [`${ ROOT }/issue-agent.sh`, 'list'], { encoding: 'utf8' });\n\n  return out.split('\\n').filter(Boolean).map((line) => line.split('\\t')[0]).filter(Boolean);\n}\n\n/**\n * Is this item finished with?\n *\n * Unreachable is NOT finished. A rate limit, a network blip or a renamed field must never read\n * as \"closed\", because the answer deletes a conversation and there is no getting it back.\n */\nasync function isDone(key) {\n  if (key.startsWith('#')) {\n    const resp = await fetch(\n      `https://api.github.com/repos/${ REPO_OWNER }/${ REPO_NAME }/issues/${ key.slice(1) }`,\n      { headers: { Authorization: `Bearer ${ creds.GH_TOKEN }`, Accept: 'application/vnd.github+json' } },\n    );\n\n    if (!resp.ok) {\n      return { done: false, why: `github said ${ resp.status }` };\n    }\n\n    const issue = await resp.json();\n\n    return issue.state === 'closed'\n      ? { done: true, why: `closed ${ (issue.closed_at || '').slice(0, 10) }` }\n      : { done: false, why: `still ${ issue.state }` };\n  }\n\n  const resp = await fetch(`${ JIRA_BASE }/rest/api/2/issue/${ encodeURIComponent(key) }?fields=status,resolution`, {\n    headers: { Authorization: `Bearer ${ creds.JIRA_PAT }`, Accept: 'application/json' },\n  });\n\n  if (!resp.ok) {\n    return { done: false, why: `jira said ${ resp.status }` };\n  }\n\n  const fields = (await resp.json()).fields || {};\n  const category = fields.status?.statusCategory?.key || '';\n\n  // Jira's own answer to \"is this finished\": the status category, not the status name, which\n  // every project spells differently. A resolution alone is not enough - a ticket can carry\n  // one and be reopened.\n  return category === 'done'\n    ? { done: true, why: `${ fields.status?.name } (${ fields.resolution?.name || 'no resolution' })` }\n    : { done: false, why: `${ fields.status?.name || 'unknown' }` };\n}\n\nconst today = todaysKeys();\nconst absent = agents().filter((key) => !today.has(key));\n\nprocess.stderr.write(`issue-prune: ${ absent.length } agents whose item is not in today's report\\n`);\n\nlet ended = 0;\n\nfor (const key of absent) {\n  const verdict = await isDone(key);\n\n  if (!verdict.done) {\n    process.stderr.write(`issue-prune: keeping ${ key } - ${ verdict.why }\\n`);\n    continue;\n  }\n\n  if (DRY) {\n    process.stderr.write(`issue-prune: would end ${ key } - ${ verdict.why }\\n`);\n    continue;\n  }\n\n  execFileSync('/bin/sh', [`${ ROOT }/issue-agent.sh`, 'end', key], { encoding: 'utf8' });\n  ended++;\n  process.stderr.write(`issue-prune: ended ${ key } - ${ verdict.why }\\n`);\n}\n\nprocess.stderr.write(`issue-prune: ${ ended } ended, ${ absent.length - ended } kept\\n`);\n",
  "issue-round.sh": "#!/bin/sh\n# Ask every item's own agent about its own item, one at a time.\n#\n# The report used to be one agent reading everything and writing everything, so what it learned\n# about a ticket died with the run. Each item has a standing agent now (issue-agent.sh), and\n# this is the round that visits them: it hands each one today's facts about ITS item and\n# collects what comes back, verbatim, into contributions.json.\n#\n# The reporter does not write these. It assembles them, and decides one thing of its own - what\n# to act on first - after everybody has reported.\n#\n#   issue-round.sh <run-dir>\n#\n# THE CLASS IS COMPUTED HERE, not asked of an agent. ACT_NOW / FOLLOW_UP / WAITING / TRACKED is\n# a lookup on precomputed fields with \"first match wins\" - one right answer, no judgement in it.\n# Thirty agents each applying that table to their own item would drift, invisibly, because each\n# one only ever sees its own item. So the arithmetic is done once, in code, and handed to the\n# agent as a fact. What is left for the agent is what only it can know: what changed since it\n# last looked, and what it recommends.\n#\n# Sequential on purpose. These share one pod with no resource limits, on the node that runs\n# Rancher, and a herd of claudes is how that node has been taken down before.\nset -e\n\nDIR=${1:?issue-round.sh needs the run directory}\n[ -f \"$DIR/data.json\" ] || { echo \"issue-round.sh: no data.json in $DIR\" >&2; exit 2; }\n\nROOT=$(dirname \"$0\")\nAGENT=\"$ROOT/issue-agent.sh\"\n[ -x \"$AGENT\" ] || AGENT=\"sh $ROOT/issue-agent.sh\"\n\nWORK=\"$DIR/issue-round\"\nmkdir -p \"$WORK\"\n\n# One file per item: its data, its computed class, and the shape of the answer wanted back.\nnode -e '\nconst fs = require(\"fs\");\nconst [dataPath, workDir, brief] = process.argv.slice(1);\nconst d = JSON.parse(fs.readFileSync(dataPath, \"utf8\"));\n\n// The rule table, as code. Order matters: first match wins.\nfunction githubClass(i) {\n  if (i.tracked) return { cls: \"TRACKED\", rule: \"github.1 tracked\" };\n  if (i.ball === \"ours\") return { cls: \"ACT_NOW\", rule: \"github.2 ball is ours\" };\n  if (i.ball === \"reporter\" && i.idle_days >= 14) return { cls: \"FOLLOW_UP\", rule: \"github.3 reporter, idle >= 14\" };\n  if (i.ball === \"reporter\") return { cls: \"WAITING\", rule: \"github.4 reporter, idle < 14\" };\n\n  return { cls: \"ACT_NOW\", rule: \"github.fallback\" };\n}\n\n// Jira, mirroring the prompt\\u2019s own list, first match wins:\n//   1. last comment from the reporter/external, or no comments  -> ACT_NOW (we owe the move)\n//   2. we commented last, OR status is Waiting for Reporter      -> FOLLOW_UP >= 14d, else WAITING\n//   3. assigned AND a GH issue/PR moving                         -> TRACKED\n//\n// The honest caveat: rule 1 needs to know whether the last commenter is one of US, and Jira\n// items carry no association field the way GitHub ones do. The mechanical proxy is\n// `last_comment_author === reporter`, which is right whenever the reporter is the one who\n// spoke, and treats an unrelated third party as if they were us. So the matched rule is\n// recorded beside the class, and an agent that thinks its item is misclassified says so in\n// `class_dispute` rather than quietly using a different one - a disagreement anybody can see\n// beats a drift nobody can.\nfunction jiraClass(t) {\n  const waitingForReporter = /waiting for reporter/i.test(t.status || \"\");\n  const reporterSpokeLast = !!t.last_comment_author && t.last_comment_author === t.reporter;\n  const assignedAndMoving = !!t.github_issue && !!t.assignee && t.assignee !== \"Unassigned\";\n\n  if (!t.comments_count || reporterSpokeLast) {\n    return { cls: \"ACT_NOW\", rule: \"jira.1 reporter spoke last or no comments\" };\n  }\n\n  if (waitingForReporter || t.last_comment_author) {\n    return t.idle_days >= 14\n      ? { cls: \"FOLLOW_UP\", rule: \"jira.2 ours/waiting-for-reporter, idle >= 14\" }\n      : { cls: \"WAITING\", rule: \"jira.2 ours/waiting-for-reporter, idle < 14\" };\n  }\n\n  if (assignedAndMoving) {\n    return { cls: \"TRACKED\", rule: \"jira.3 assigned and a GH issue moving\" };\n  }\n\n  return { cls: \"ACT_NOW\", rule: \"jira.fallback\" };\n}\n\n// What this item looked like the last time its agent saw it. An agent that remembers the\n// ticket does not need the description and twenty-four comments again - it needs what is NEW.\n// Re-sending everything every day would pay for the memory and then not use it.\nfunction lastSeen(ref) {\n  const slug = ref.toLowerCase().replace(/[^a-z0-9-]+/g, \"-\").replace(/^-+|-+$/g, \"\").slice(0, 60);\n  const file = `${ process.env.ISSUE_AGENT_ROOT || \"/workspace/idr-issues\" }/${ slug }/last-seen.json`;\n\n  try {\n    return JSON.parse(fs.readFileSync(file, \"utf8\"));\n  } catch {\n    return null;\n  }\n}\n\nconst items = [];\n\nfor (const i of d.github?.external_issues?.issues || []) {\n  items.push({ ref: `#${ i.number }`, kind: \"github\", group: \"issues\", ...githubClass(i), item: i });\n}\nfor (const i of d.github?.questions?.issues || []) {\n  items.push({ ref: `#${ i.number }`, kind: \"github\", group: \"questions\", ...githubClass(i), item: i });\n}\nfor (const [group, arr] of Object.entries(d.jira || {})) {\n  for (const t of (Array.isArray(arr) ? arr : arr?.issues || [])) {\n    items.push({ ref: t.key, kind: \"jira\", group, ...jiraClass(t), item: t });\n  }\n}\n\nfs.writeFileSync(`${ workDir }/items.json`, JSON.stringify(items));\n\n// The prompt each agent gets. Its own item and nothing else: an agent that could see the\n// whole board would start reporting on items that are not its own.\nfor (const [n, it] of items.entries()) {\n  const seen = lastSeen(it.ref);\n  const i = it.item;\n  const comments = Array.isArray(i.comments) ? i.comments : [];\n  const fresh = seen\n    ? comments.filter((c) => !seen.last_comment_at || String(c.created || c.created_at || \"\") > seen.last_comment_at)\n    : comments;\n\n  // First look gets everything. Every look after it gets the delta and nothing else: the agent\n  // is the one carrying the history, which is the whole reason it exists.\n  const payload = seen ? {\n    ref:                  it.ref,\n    status:               i.status || (i.tracked ? \"tracked\" : undefined),\n    status_was:           seen.status,\n    // Two clocks, deliberately. The first is how long since WE replied, which is what the\n    // nudge rule measures; the second is how long the reporter has been quiet, which nothing\n    // we do resets. They come apart exactly when we have been chasing somebody who is not\n    // answering - which is when it matters most.\n    idle_days:            i.idle_days,\n    reporter_silent_days: i.reporter_silent_days,\n    new_comments:         fresh,\n    nothing_new:          !fresh.length && i.status === seen.status,\n  } : i;\n\n  const lines = [\n    `You are the standing agent for ${ it.kind === \"jira\" ? \"Jira ticket\" : \"GitHub issue\" } ${ it.ref }.`,\n    `Today is ${ d.report_date }.`,\n    \"\",\n    `Read ${ brief } IN FULL before you answer. It is your standing brief and it is authoritative.`,\n    \"\",\n    seen\n      ? \"What is NEW since you last looked (you already know the rest - it is not sent twice):\"\n      : \"Your item (first look - everything you get today):\",\n    \"```json\",\n    JSON.stringify(payload, null, 1),\n    \"```\",\n    \"\",\n    `Class today: **${ it.cls }** (rule: ${ it.rule }). Computed, not your decision - see the brief.`,\n    \"\",\n    \"Reply with ONE json object and nothing else - no fence, no commentary. Only these keys:\",\n    \"\",\n    JSON.stringify({\n      changed:           \"one line: what changed since you last looked, or \\\"first look\\\"\",\n      last_activity:     { who: \"reporter | us | nobody\", days_ago: 0, context: \"one short sentence\" },\n      next_step:         { verb: \"one of the verbs in the brief\", explanation: \"one to three plain sentences\" },\n      suggested_comment: \"copy-pasteable draft, plain text - or null for a GitHub issue that needs none\",\n      quick_action:      null,\n      class_dispute:     \"\",\n    }, null, 1),\n    \"\",\n    \"Do not repeat the item\\u2019s facts back - its key, url, title, dates and links are already\",\n    \"known and will be filled in around your answer. Judgement is what is wanted from you.\",\n  ];\n\n  fs.writeFileSync(`${ workDir }/${ String(n).padStart(3, \"0\") }.prompt`, lines.join(\"\\n\"));\n}\n\nprocess.stderr.write(`issue-round: ${ items.length } items\\n`);\n' \"$DIR/data.json\" \"$WORK\" \"$ROOT/issue-brief.md\"\n\n# Ask each one, in turn. A failure is recorded against that item rather than ending the round:\n# one agent that times out should cost one contribution, not the report.\nnode -e '\nconst fs = require(\"fs\");\nconst { execFileSync } = require(\"child_process\");\nconst [workDir, agent] = process.argv.slice(1);\nconst items = JSON.parse(fs.readFileSync(`${ workDir }/items.json`, \"utf8\"));\nconst out = {};\n\n/** One finished report item: the data\\u2019s facts, wrapped around the agent\\u2019s words. */\nfunction reportItem(it, said) {\n  const i = it.item;\n  const judgement = {\n    class_dispute:     said.class_dispute || \"\",\n    changed:           said.changed || \"\",\n    next_step:         said.next_step || null,\n    suggested_comment: said.suggested_comment ?? null,\n  };\n\n  if (it.kind === \"jira\") {\n    return {\n      key:           i.key,\n      url:           i.url,\n      title:         i.summary,\n      class:         it.cls,\n      priority:      i.priority || null,\n      age_days:      i.age_days ?? null,\n      idle_days:     i.idle_days ?? null,\n      reporter_silent_days: i.reporter_silent_days ?? null,\n      assignee:      i.assignee || null,\n      github_issue:  i.github_issue || null,\n      last_activity: said.last_activity || null,\n      quick_action:  said.quick_action || null,\n      ...judgement,\n    };\n  }\n\n  const base = {\n    number:     i.number,\n    url:        i.url,\n    title:      i.title,\n    age_days:   i.age_days ?? null,\n    idle_days:  i.idle_days ?? null,\n    reporter_silent_days: i.reporter_silent_days ?? null,\n    ...judgement,\n  };\n\n  // A question has no class and no kind line; an issue has both.\n  return it.group === \"questions\" ? base : {\n    ...base,\n    class:          it.cls,\n    comments_count: i.comments_count ?? null,\n    kind:           (i.labels || []).join(\", \") || null,\n    linked_prs:     i.linked_prs || [],\n  };\n}\n\nfor (const [n, it] of items.entries()) {\n  const prompt = `${ workDir }/${ String(n).padStart(3, \"0\") }.prompt`;\n  const argv = agent.split(\" \").concat([\"ask\", it.ref, prompt]);\n\n  process.stderr.write(`issue-round: ${ it.ref } (${ n + 1 }/${ items.length }) ${ it.cls }\\n`);\n\n  try {\n    let answer = execFileSync(argv[0], argv.slice(1), { encoding: \"utf8\", timeout: 600000 });\n    let match = answer.match(/\\{[\\s\\S]*\\}/);\n    let said = match ? JSON.parse(match[0]) : null;\n\n    // One re-ask when the draft is over length, with the number in it.\n    //\n    // The brief has asked for a short comment twice now and been ignored twice - not out of\n    // defiance, but because an agent reusing the previous draft has no way to know it is over\n    // length, and asking a model to count its own characters is asking the wrong thing.\n    // Measured across three runs: explanations, which are written fresh each time, came down\n    // from 604 to 490; comments, which are carried forward, stayed at 1100 with eight of nine\n    // byte-identical. A number it cannot argue with is the thing that was missing.\n    //\n    // Once, not in a loop: a second failure is worth reporting, not worth paying for again.\n    const LIMIT = 700;\n    const draft = said?.suggested_comment;\n\n    if (typeof draft === \"string\" && draft.length > LIMIT) {\n      const again = `${ workDir }/${ String(n).padStart(3, \"0\") }.retry`;\n\n      fs.writeFileSync(again, [\n        `Your suggested_comment for ${ it.ref } is ${ draft.length } characters. The limit is ${ LIMIT }.`,\n        \"\",\n        \"Send the same JSON object again with the same content and the same meaning, but with\",\n        \"suggested_comment cut to something a person would actually paste into a ticket. Keep\",\n        \"the ask and the specifics; drop the preamble, the restatement and the second example.\",\n        \"Everything else in the object stays exactly as it was.\",\n      ].join(\"\\n\"));\n\n      process.stderr.write(`issue-round: ${ it.ref } comment ${ draft.length } chars, asking once for shorter\\n`);\n\n      try {\n        answer = execFileSync(argv[0], argv.slice(1, -1).concat([again]), { encoding: \"utf8\", timeout: 600000 });\n        match = answer.match(/\\{[\\s\\S]*\\}/);\n\n        const shorter = match ? JSON.parse(match[0]) : null;\n\n        if (typeof shorter?.suggested_comment === \"string\" && shorter.suggested_comment.length < draft.length) {\n          said = shorter;\n        }\n      } catch {\n        // Keep the long one. Over length beats absent.\n      }\n    }\n\n    // The report item: facts from the data, judgement from the agent. The agent is never asked\n    // to type back a key, a url or a date it was handed - a transcription error in a fact is\n    // both likelier and worse than one in prose, and the data already has them right.\n    out[it.ref] = {\n      ...it, ok: true, contribution: said, raw: match ? undefined : answer.slice(0, 500), item: undefined,\n      report: said ? reportItem(it, said) : null,\n    };\n\n    // Only after it answered. A turn that failed did not see today, so tomorrow should still\n    // offer it what it missed rather than skip straight past.\n    const slug = it.ref.toLowerCase().replace(/[^a-z0-9-]+/g, \"-\").replace(/^-+|-+$/g, \"\").slice(0, 60);\n    const dir = `${ process.env.ISSUE_AGENT_ROOT || \"/workspace/idr-issues\" }/${ slug }`;\n\n    try {\n      fs.mkdirSync(dir, { recursive: true });\n      fs.writeFileSync(`${ dir }/last-seen.json`, JSON.stringify({\n        at:               new Date().toISOString(),\n        status:           it.item.status || null,\n        idle_days:        it.item.idle_days ?? null,\n        comments_count:   it.item.comments_count ?? null,\n        last_comment_at:  it.item.last_comment_at || null,\n      }));\n    } catch { /* the agent answered; failing to note it is not worth losing that */ }\n  } catch (e) {\n    // Exit 3 is the agent standing down because somebody is mid-conversation with it right\n    // now. That is the right outcome: a person typing outranks the nightly round, and what\n    // they say will be in the transcript this round would have resumed anyway.\n    //\n    // It is no longer the answer for a chat merely being OPEN. A pane closed in the browser\n    // leaves a claude running on an abandoned pty, and that used to count as \"busy\" forever:\n    // one item reported nothing for four days while every report said its chat was open.\n    // issue-agent.sh now reaps an idle holder instead, so exit 3 means a live conversation.\n    const busy = e?.status === 3;\n\n    out[it.ref] = {\n      ...it,\n      ok:    false,\n      busy,\n      error: busy\n        ? \"somebody is talking to it right now, so the round left it alone - it will report next time\"\n        : String(e.message || e).slice(0, 300),\n    };\n    process.stderr.write(`issue-round: ${ it.ref } FAILED - ${ out[it.ref].error }\\n`);\n  }\n}\n\nfs.writeFileSync(`${ workDir }/../contributions.json`, JSON.stringify(out, null, 1));\nprocess.stderr.write(`issue-round: wrote contributions.json (${ Object.values(out).filter((x) => x.ok).length }/${ items.length } answered)\\n`);\n' \"$WORK\" \"$AGENT\"\n\n# Ending the agents whose items are finished with.\n#\n# After the round rather than before it: an item that is in today's report is not a candidate,\n# and one that has just been asked should not be ended a moment later. Guarded, because\n# pruning is housekeeping - a report that cannot tidy up is still a report.\nif [ -f \"$ROOT/issue-prune.mjs\" ]; then\n  node \"$ROOT/issue-prune.mjs\" \"$DIR\" || echo \"issue-round: pruning did not finish; nothing was ended\" >&2\nfi\n",
  "publish.sh": "#!/bin/sh\n# Put one finished run into the cluster, where the extension reads it back.\n#\n# Two ConfigMaps per report, and the split is the whole reason this is a script. The summary is\n# small and every one of them is fetched to draw the list; the payload is the report itself and\n# is fetched only when somebody opens it. Keeping them in one object would mean the list page\n# downloading a hundred reports in full to render a hundred rows of dates.\n#\n# The agent calls this rather than composing kubectl itself: the labels are what the extension\n# selects on, so a report published with a typo'd label is a report that exists and cannot be\n# found. It is also where the hundred-report cap is enforced, because publishing is the only\n# moment the cap can be exceeded.\n#\n# usage: publish.sh <run-dir> <report-id> done\n#        publish.sh <run-dir> <report-id> fail \"one-line reason\"\nset -e\n\nDIR=${1:?publish.sh needs the run directory}\nID=${2:?publish.sh needs the report id}\nRESULT=${3:?publish.sh needs done or fail}\nMESSAGE=${4:-}\n\nNS=interrupt-duty-reports-console\nLABEL=interrupt-duty.rancher.io\nKEEP=${KEEP_REPORTS:-100}\n\n# A ConfigMap holds at most 1 MiB. A report that does not fit has to fail as a report rather\n# than as a kubectl error nobody will read, so it is checked before anything is applied.\nMAX_REPORT_BYTES=900000\n\n# Whose kubectl.\n#\n# shell.sh gives a pane the Rancher identity of whoever opened it (seed/rancher-credential.sh),\n# which is the right credential to write with: attributable, and no more rights than that\n# person has. But it is only there once somebody has opened the agents drawer at least once,\n# and it can be expired - so the pod's own ServiceAccount, which is always mounted, is the\n# fallback. KUBECONFIG naming nothing is what sends kubectl to the in-cluster config.\nKUBE_FALLBACK=''\n\nkube() {\n  if [ -n \"$KUBE_FALLBACK\" ]; then\n    KUBECONFIG=/dev/null kubectl \"$@\"\n  else\n    kubectl \"$@\"\n  fi\n}\n\nif ! kubectl auth can-i create configmaps --namespace \"$NS\" >/dev/null 2>&1; then\n  KUBE_FALLBACK=yes\nfi\n\n# Whatever happens from here, the tokens do not outlive the run.\ncleanup_credentials() {\n  rm -f \"$DIR/creds.json\"\n}\n\n# Re-applied on both paths, so a run that fails still leaves a row saying so rather than one\n# stuck on \"running\" until somebody notices.\napply_summary() {\n  kube create configmap \"$ID\" \\\n    --namespace \"$NS\" \\\n    --from-file=meta.json=\"$DIR/meta.json\" \\\n    --dry-run=client -o json |\n    node -e '\n      const [id, label] = process.argv.slice(1);\n      let raw = \"\";\n\n      process.stdin.on(\"data\", (c) => (raw += c));\n      process.stdin.on(\"end\", () => {\n        const cm = JSON.parse(raw);\n\n        cm.metadata.labels = {\n          [`${ label }/report`]: \"summary\",\n          [`${ label }/report-id`]: id,\n        };\n        process.stdout.write(JSON.stringify(cm));\n      });\n    ' \"$ID\" \"$LABEL\" |\n    kube apply -f - >/dev/null\n}\n\nfinish_failed() {\n  cleanup_credentials\n  node -e '\n    const fs = require(\"fs\");\n    const [file, message] = process.argv.slice(1);\n    const meta = JSON.parse(fs.readFileSync(file, \"utf8\"));\n\n    meta.status = \"failed\";\n    meta.error = String(message || \"the run failed\").replace(/\\s+/g, \" \").trim().slice(0, 500);\n    meta.finishedAt = new Date().toISOString();\n    fs.writeFileSync(file, JSON.stringify(meta));\n  ' \"$DIR/meta.json\" \"$1\"\n  apply_summary\n  echo \"publish.sh: recorded a failure for $ID - $1\"\n  exit 0\n}\n\n# The cap, oldest first. Report ids are `daily-<date>-<time>`, so sorting the names sorts them\n# by when they were made, and everything past the newest $KEEP goes - the payload with the\n# summary, since a payload whose summary is gone can never be opened again.\nprune() {\n  kube get configmaps --namespace \"$NS\" \\\n    -l \"$LABEL/report=summary\" \\\n    -o \"jsonpath={range .items[*]}{.metadata.name}{\\\"\\n\\\"}{end}\" 2>/dev/null |\n    sort -r |\n    tail -n \"+$((KEEP + 1))\" |\n    while read -r old; do\n      [ -n \"$old\" ] || continue\n      echo \"publish.sh: pruning $old (over the $KEEP-report cap)\"\n      kube delete configmap --namespace \"$NS\" --ignore-not-found \"$old\" \"$old-report\" >/dev/null 2>&1 || true\n    done\n}\n\n[ -f \"$DIR/meta.json\" ] || { echo \"publish.sh: $DIR/meta.json is missing - the run was not set up\" >&2; exit 2; }\n\nkube get namespace \"$NS\" >/dev/null 2>&1 || kube create namespace \"$NS\" >/dev/null\n\nif [ \"$RESULT\" = fail ]; then\n  finish_failed \"$MESSAGE\"\nfi\n\n[ \"$RESULT\" = done ] || { echo \"publish.sh: the result must be done or fail, not '$RESULT'\" >&2; exit 2; }\n\n# The report has to be a report before any of it is published. An agent that wrote prose, or\n# stopped halfway through the JSON, must land as a failure somebody can see - not as a row that\n# opens onto an error.\nVALIDATION=$(node -e '\n  const fs = require(\"fs\");\n  const [reportFile, metaFile, maxBytes] = process.argv.slice(1);\n  const fail = (m) => {\n    process.stdout.write(`INVALID ${ m }`);\n    process.exit(0);\n  };\n\n  let text;\n\n  try {\n    text = fs.readFileSync(reportFile, \"utf8\");\n  } catch (e) {\n    fail(`report.json was never written (${ e.code || e.message })`);\n  }\n\n  if (Buffer.byteLength(text) > Number(maxBytes)) {\n    fail(`report.json is ${ Math.round(Buffer.byteLength(text) / 1024) } KiB, over what a ConfigMap can hold`);\n  }\n\n  let report;\n\n  try {\n    report = JSON.parse(text);\n  } catch (e) {\n    fail(`report.json is not valid JSON: ${ e.message }`);\n  }\n\n  if (!report || typeof report !== \"object\" || Array.isArray(report)) {\n    fail(\"report.json is not a JSON object\");\n  }\n\n  const groups = {\n    \"jira.new\":              report.jira?.new,\n    \"jira.in_triage\":        report.jira?.in_triage,\n    \"jira.waiting_reporter\": report.jira?.waiting_reporter,\n    \"github.issues\":         report.github?.issues,\n    \"github.questions\":      report.github?.questions,\n  };\n\n  for (const [name, value] of Object.entries(groups)) {\n    if (!Array.isArray(value)) {\n      fail(`report.json is missing the ${ name } array`);\n    }\n  }\n\n  if (!Array.isArray(report.top3)) {\n    fail(\"report.json is missing the top3 array\");\n  }\n\n  // Taken from the arrays rather than from what the agent wrote beside them: these are what the\n  // list shows without opening anything, and a count that disagrees with the report it labels\n  // is worse than no count.\n  const counts = {\n    jira_new:              groups[\"jira.new\"].length,\n    jira_in_triage:        groups[\"jira.in_triage\"].length,\n    jira_waiting_reporter: groups[\"jira.waiting_reporter\"].length,\n    github_new:            groups[\"github.issues\"].length,\n    github_questions:      groups[\"github.questions\"].length,\n  };\n  const actNow = Object.values(groups).flat().filter((item) => item?.class === \"ACT_NOW\").length;\n  const meta = JSON.parse(fs.readFileSync(metaFile, \"utf8\"));\n\n  meta.status = \"complete\";\n  meta.finishedAt = new Date().toISOString();\n  meta.reportDate = report.report_date || meta.reportDate;\n  meta.headline = String(report.reminder?.line || \"\").slice(0, 400);\n  meta.counts = counts;\n  meta.actNow = actNow;\n  meta.top3 = (report.top3 || []).slice(0, 3).map((t) => ({\n    ref:   String(t?.ref || \"\").slice(0, 40),\n    title: String(t?.title || \"\").slice(0, 200),\n    class: String(t?.class || \"\").slice(0, 20),\n  }));\n  delete meta.error;\n\n  fs.writeFileSync(metaFile, JSON.stringify(meta));\n  process.stdout.write(\"OK\");\n' \"$DIR/report.json\" \"$DIR/meta.json\" \"$MAX_REPORT_BYTES\" 2>&1) || VALIDATION=\"INVALID publish.sh could not read the report: $VALIDATION\"\n\ncase \"$VALIDATION\" in\n  OK) ;;\n  INVALID*) finish_failed \"${VALIDATION#INVALID }\" ;;\n  *) finish_failed \"publish.sh could not validate the report: $VALIDATION\" ;;\nesac\n\n# The payload first. A summary that says \"complete\" while the report it points at is not there\n# yet is a row somebody can click on and get nothing.\nkube create configmap \"$ID-report\" \\\n  --namespace \"$NS\" \\\n  --from-file=report.json=\"$DIR/report.json\" \\\n  --dry-run=client -o json |\n  node -e '\n    const [id, label] = process.argv.slice(1);\n    let raw = \"\";\n\n    process.stdin.on(\"data\", (c) => (raw += c));\n    process.stdin.on(\"end\", () => {\n      const cm = JSON.parse(raw);\n\n      cm.metadata.labels = {\n        [`${ label }/report`]: \"payload\",\n        [`${ label }/report-id`]: id,\n      };\n      process.stdout.write(JSON.stringify(cm));\n    });\n  ' \"$ID\" \"$LABEL\" |\n  kube apply -f - >/dev/null\n\napply_summary\ncleanup_credentials\nprune\n\necho \"publish.sh: published $ID\"\n",
  "run.sh": "#!/bin/sh\n# Gather one run's data. Called by the agent as its first step.\n#\n# A script rather than a line in the prompt, so the one part of the run that must be identical\n# every day is identical every day: the agent's job starts at data.json and stops at\n# report.json, and neither end of that is left to it to improvise.\n#\n# It also resolves the two credentials, and does that here rather than in the browser. A token\n# pasted into a page used to be written into this pod over the exec socket for every run; now it\n# is stored once in a Secret and read at the moment it is needed, by the pod, with the pod's own\n# ServiceAccount. The browser never holds one, so there is nothing for it to leak.\n#\n# usage: run.sh <run-dir> <user-slug>\nset -e\n\nDIR=${1:?run.sh needs the run directory}\n# Whose credentials. They are stored per Rancher user, so a report is generated with the access\n# of the person who asked for it rather than with one shared account nobody can identify.\nSEED=$(dirname \"$0\")\n\n[ -d \"$DIR\" ] || { echo \"run.sh: no such run directory: $DIR\" >&2; exit 2; }\n\nNS=interrupt-duty-reports-console\n# Settings are shared by every console in this family, not kept beside each one's own data.\nSECRET_NS=ui-internal-tools\nSECRET=settings\n\n# kubectl as the pod rather than as whoever opened a terminal in it. shell.sh writes a kubeconfig\n# carrying the Rancher identity of the person who opened the pane (seed/rancher-credential.sh),\n# and that identity may not be allowed to read these Secrets - the pod's ServiceAccount is. A\n# KUBECONFIG naming nothing is what sends kubectl to the in-cluster config.\nsecret_key() {\n  KUBECONFIG=/dev/null kubectl get secret \"$2\" -n \"$1\" -o \"jsonpath={.data.$3}\" 2>/dev/null \\\n    | base64 -d 2>/dev/null \\\n    | tr -d '\\r\\n'\n}\n\nGH_TOKEN=$(secret_key \"$SECRET_NS\" \"$SECRET\" \"gh_token\")\nJIRA_PAT=$(secret_key \"$SECRET_NS\" \"$SECRET\" \"jira_pat\")\n\nmissing=''\n[ -n \"$JIRA_PAT\" ] || missing=\"a Jira token\"\n[ -n \"$GH_TOKEN\" ] || missing=\"${missing:+$missing and }a GitHub token\"\n\nif [ -n \"$missing\" ]; then\n  echo \"run.sh: $missing is not stored for this user. Set it from the Credentials dialog.\" >&2\n  exit 2\nfi\n\n# 0600 before anything is in it, so it is never briefly readable, and owned by the pane's user\n# because that is who runs the gather. Removed by publish.sh however the run ends.\nCREDS=\"$DIR/creds.json\"\n\n: > \"$CREDS\"\nchmod 600 \"$CREDS\"\n\n# Through node rather than printf, so a token containing a quote or a backslash is JSON-encoded\n# rather than pasted into a string and hoped for.\nGH_TOKEN=\"$GH_TOKEN\" JIRA_PAT=\"$JIRA_PAT\" node -e \\\n  'require(\"fs\").writeFileSync(process.argv[1], JSON.stringify({ JIRA_PAT: process.env.JIRA_PAT, GH_TOKEN: process.env.GH_TOKEN }))' \\\n  \"$CREDS\"\n\nCREDS_FILE=\"$CREDS\" OUT=\"$DIR/data.json\" node \"$SEED/gather.mjs\"\n\necho \"run.sh: wrote $DIR/data.json\"\n",
};
